            <h2 class="plan-name">Team</h2>
            <p class="plan-price">$49<small> / month</small></p>
            <p class="muted">For a small office.</p>
            <ul class="plan-features">
              <li>Ten items a month</li>
              <li>One invoice for everyone</li>
              <li>A named contact</li>
            </ul>
            <a class="btn btn-secondary" href="contact.html">Choose Team</a>
          </div>
        </div>
      </div>
    </section>
